def generate_professional_signature(user_context, system_context, action_context):
    """
    生成专业签名，根据用户角色、系统状态和操作上下文动态调整
    """

    base_signature = """
<div class="quant-signature" style="border-top: 2px solid #3182ce; margin-top: 20px; padding-top: 15px; font-family: 'Inter', sans-serif;">
    <div style="display: flex; justify-content: space-between; align-items: center;">
