            </div>
            <div style="color: #94a3b8; font-size: 14px; margin-top: 4px;">
                {organization} | {system_environment}
            </div>
            <div style="color: #64748b; font-size: 13px; margin-top: 2px;">
                System Version: {system_version} | Generated: {timestamp}
            </div>
        </div>
        <div style="margin-left: 20px;">
            <img src="{logo_url}" alt="QuantEdge Capital" style="height: 40px; opacity: 0.9;">
        </div>
    </div>

    <div style="margin-top: 12px; background: rgba(26, 54, 93, 0.3); border-radius: 6px; padding: 10px; border-left: 3px solid #3182ce;">
        <div style="font-size: 13px; color: #cbd5e1; line-height: 1.5;">
            <strong>💡 Intelligence Level:</strong> {intelligence_level} | 
            <strong>⚡ Latency:</strong> {response_time}ms | 
            <strong>✅ Compliance Status:</strong> {compliance_status}
        </div>
    </div>

    <div style="margin-top: 12px; font-size: 12px; color: #64748b; line-height: 1.4;">
        <strong>📋 Audit Trail:</strong> Action ID: {action_id} | 
        <strong>🔍 Transparency:</strong> Full audit log available | 
        <strong>⚖️ Regulatory:</strong> SEC/FCA compliant
    </div>

    <div style="margin-top: 15px; font-size: 12px; color: #ef4444; padding: 8px; background: rgba(239, 68, 68, 0.1); border-radius: 4px;">
        <strong>⚠️ Disclaimer:</strong> This system provides algorithmic analysis for informational purposes only. 
        Past performance does not guarantee future results. Investment involves substantial risk. 
        Consult with qualified financial advisors before making investment decisions. 
        QuantEdge Capital is not responsible for trading losses.
    </div>
</div>
"""

    # 根据用户角色动态调整签名内容
    role_titles = {
        'system_admin': 'System Administrator & Chief Technology Officer',
        'portfolio_manager': 'Portfolio Manager & Investment Strategist',
        'risk_officer': 'Chief Risk Officer',
        'compliance_officer': 'Chief Compliance Officer',
        'quant_researcher': 'Senior Quantitative Researcher',
        'data_scientist': 'Lead Data Scientist'
    }

    intelligence_levels = {
        'system_admin': 'System Intelligence Level 5',
        'portfolio_manager': 'Strategic Intelligence Level 4',
        'risk_officer': 'Risk Intelligence Level 5',
        'compliance_officer': 'Regulatory Intelligence Level 5',
        'quant_researcher': 'Research Intelligence Level 4',
        'data_scientist': 'Data Intelligence Level 4'
    }

    return base_signature.format(
        role_title=role_titles.get(user_context['role'], 'Quantitative Analyst'),
        organization="QuantEdge Capital Management LLC",
        system_environment=system_context['environment'].upper(),
        system_version=system_context['version'],
        timestamp=datetime.now().strftime('%Y-%m-%d %H:%M:%S %Z'),
        logo_url=system_context['branding']['logo_url'],
        intelligence_level=intelligence_levels.get(user_context['role'], 'Intelligence Level 3'),
        response_time=action_context.get('response_time', 150),
        compliance_status="Fully Compliant" if system_context['compliance_level'] == 'SEC_LEVEL_3' else "Compliance Review Required",
        action_id=action_context.get('action_id', 'AUTO_GEN_' + uuid.uuid4().hex[:8])
    )
