```python
# ~/.openclaw/monitoring/identity_health_check.py
import json
import requests
from datetime import datetime, timedelta

class IdentityHealthMonitor:
    def __init__(self):
        self.config_path = "~/.openclaw/config/identity_config.json"
        self.health_check_interval = 300  # 5 minutes
        self.alert_thresholds = {
            'identity_mismatch': 1,
            'branding_failure': 1,
            'compliance_degradation': 1,
            'certificate_expiry': 30  # days
        }

    def run_health_check(self):
        """执行身份健康检查"""
        results = {
            'timestamp': datetime.now().isoformat(),
            'status': 'healthy',
            'checks': {}
        }

        # 1. 检查系统身份配置
        identity_check = self.check_identity_configuration()
        results['checks']['identity'] = identity_check

        # 2. 检查品牌一致性
        branding_check = self.check_branding_consistency()
        results['checks']['branding'] = branding_check

        # 3. 检查合规状态
        compliance_check = self.check_compliance_status()
        results['checks']['compliance'] = compliance_check

        # 4. 检查证书状态
        certificate_check = self.check_certificate_status()
        results['checks']['certificates'] = certificate_check

        # 5. 检查身份服务可用性
        service_check = self.check_identity_services()
        results['checks']['services'] = service_check

        # 评估整体状态
        if any(check['status'] == 'critical' for check in results['checks'].values()):
            results['status'] = 'critical'
        elif any(check['status'] == 'warning' for check in results['checks'].values()):
            results['status'] = 'warning'

        # 记录和告警
        self.log_results(results)
        self.trigger_alerts(results)

        return results

    def check_identity_configuration(self):
        """检查身份配置完整性"""
        try:
            with open(self.config_path, 'r') as f:
                config = json.load(f)

            required_fields = [
                'system_identity.name',
                'system_identity.display_name',
                'system_identity.organization',
                'system_identity.system_role',
                'branding.logo_url',
                'branding.color_scheme.primary'
            ]

            missing_fields = []
            for field_path in required_fields:
                parts = field_path.split('.')
                current = config
                for part in parts:
                    if part not in current:
                        missing_fields.append(field_path)
                        break
                    current = current[part]

            if missing_fields:
                return {
                    'status': 'critical',
                    'message': f'Missing required identity fields: {", ".join(missing_fields)}',
                    'details': {'missing_fields': missing_fields}
                }

            return {
                'status': 'healthy',
                'message': 'Identity configuration is complete and valid',
                'details': {
                    'system_name': config['system_identity']['name'],
                    'organization': config['system_identity']['organization'],
                    'version': config['system_identity']['version']
                }
            }

        except Exception as e:
            return {
                'status': 'critical',
                'message': f'Failed to load identity configuration: {str(e)}',
                'details': {'error': str(e)}
            }
